import React from 'react';
import type {FC} from 'react';

import {ActionTooltip, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import type {IconRefugeProps} from '../IconRefuge';
import {IconRefuge} from '../IconRefuge';

import {defaultMessages} from './i18n';

import keyResultIcon from '../../../../assets/icons/keyResult.svg';

export type KeyResultIconProps = Partial<Pick<IconRefugeProps, 'size' | 'refugeSize'>>;

export const KeyResultIcon: FC<KeyResultIconProps> = ({refugeSize = 24, size = 16}) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    return (
        <ActionTooltip title={t('title')} placement="bottom-start">
            <span>
                <IconRefuge refugeSize={refugeSize} size={size} data={keyResultIcon} />
            </span>
        </ActionTooltip>
    );
};
